export interface CuratedRepo {
 id: number;
 name: string;
 full_name: string;
 description: string;
 html_url: string;
 stargazers_count: number;
 forks_count: number;
 language: string | null;
 category: RepoCategory;
 owner: {
 login: string;
 avatar_url: string;
 };
}

export type RepoCategory =
 | 'All'
 | 'SaaS Starters'
 | 'Auth & Identity'
 | 'Databases'
 | 'AI & ML'
 | 'DevOps & Infra'
 | 'UI Components'
 | 'CMS & Content'
 | 'Payments & Billing'
 | 'Analytics'
 | 'Email & Communication'
 | 'Deployment'
 | 'Mobile'
 | 'API & Backend'
 | 'Monitoring'
 | 'Forms & Surveys'
 | 'Search'
 | 'File Storage'
 | 'Design & UI'
 | 'Productivity'
 | 'Utilities'
 | 'Privacy & Security'
 | 'Education'
 | 'Lists';

let idCounter = 0;
const repo = (
 name: string,
 full_name: string,
 description: string,
 url: string,
 stars: number,
 forks: number,
 language: string | null,
 category: RepoCategory,
 ownerLogin: string,
 ownerAvatar: string,
): CuratedRepo => ({
 id: ++idCounter,
 name,
 full_name,
 description,
 html_url: url,
 stargazers_count: stars,
 forks_count: forks,
 language,
 category,
 owner: { login: ownerLogin, avatar_url: ownerAvatar },
});

const av = (login: string) => `https://avatars.githubusercontent.com/${login}`;

